// react
import {useState, useCallback, useEffect, useRef, useMemo, useContext} from 'react'

// fontawesome
import {faXmark,faArrowUpRightFromSquare,faArrowRotateLeft,faCompress,faExpand,faDownload,faSquareMinus,faSquarePlus,faTable,faCode,faStop,faArrowsRotate,faPlus,faMinus,faAngleRight,faAngleDown, faTv} from '@fortawesome/free-solid-svg-icons'

// custom
import './App.css'

// util
import * as util from './Util.js'
Object.assign(global, util)

const fullscreenWrap = (content, aspectRatio) => {
  return (
    <div
      id='fullscreen-container'
      style={{
        position: 'fixed',
        zIndex: 100,
        left: 50,
        right: 50,
        bottom: 50,
        top: 50,
        // background: 'rgba(255,255,0,0.2)',
        overflow: 'auto',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
      }}
    >
      <div
        id='fullscreen-container1'
        style={{
          height: '100%',
          aspectRatio: aspectRatio,
          maxWidth: '100%',
          // background: 'rgba(0,255,0,0.2)',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
        }}
      >
        <div
          id='fullscreen-container2'
          style={{
            width: '100%',
            aspectRatio: aspectRatio,
            // background: 'rgba(0,0,255,0.2)',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            overflow: 'hidden',
          }}
        >
          {content}
        </div>
      </div>
    </div>
  )
}

export default function Win({
  id=null,
  title,
  addTools,
  content,
  baseDim=null,
  minimizable=true,
  fullscreenable=true,
  highlight=null,
  evaluating=false,
  evaluatingTooltip='Loading...',
  winref=null,
  bodyref=null,
  winbodystyle={},
  noshrink=false,
  minimizedwidth='auto',
  displaynoneonminimize=false,
  body_overflow='hidden',
  align_self='flex-start',
}) {
  // log('Win init '+title)

  if (id == null) id = title

  // util
  const key = (attr) => `Win_${title}_${attr}`
  
  // jotai
  const fullscreenWin = makeAtom($fullscreenWin)

  // global
  // const {fullscreenWin} = useContext(GlobalContext)

  // state
  const bodyref1 = bodyref == null ? useRef(null)
                                   : bodyref
  const winref1 = winref == null ? useRef(null)
                                 : winref
  const minimized = useStore(key('minimized'), false)
  const hover = makeState(false)
  const fullscreend = fullscreenWin?.val == winref1
  const inited = makeState(false)

  // global
  wins[id] = {win: winref1, title: title}
  // log('add to wins',id,wins[id])
  
  // fullscreen keyhandler
  const handle_key = useCallback((ev, hoverd, winref1, fullscreenWin) => {
    const key = ev.key.toLowerCase()
    const woto_focusd = document.activeElement != null && document.activeElement == window?.WOTO_NAME_INPUT?.input
    if (key=='f' && hoverd && !woto_focusd) {
      const val = fullscreenWin.val == winref1 ? null
                                             : winref1
      fullscreenWin.set(val)
    }
  }, [])
  useEffect(() => {
    if (inited.val)
      return
    const on_f = (ev) => handle_key(ev, hover.val, winref1, fullscreenWin)
    if (fullscreenable && winref1.current != null) {
      document.addEventListener('keydown', on_f)
      return () => document.removeEventListener('keydown', on_f) 
    }
    inited.set(true)
  }, [hover.val, winref1, fullscreenWin])

  // tool callbacks
  const onMinimize = useCallback(() => minimized.set(!minimized.val), 
    [minimized.val])
  const onFullscreen = useCallback((key=false) => {
    const val = fullscreenWin.val == winref1 ? null
                                             : winref1
    fullscreenWin.set(val)
  }, [fullscreenWin.val])
  const onFullFullscreen = useCallback(() => {
    if (bodyref1.current != null) {
      bodyref1.current.requestFullscreen()
    }
  }, [fullscreenWin.val])

  const tools = {
    minimize:   toolButton({
                  id: 'minimize',
                  title: minimized.val ? 'Show' : 'Hide',
                  icon:  minimized.val ? faAngleRight : faAngleDown,
                  click: onMinimize,
                }),
    evaling:    toolButton({
                  id: 'evaling',
                  title: evaluatingTooltip,
                  icon:  faArrowsRotate,
                  iconClass: 'spin',
                }),
    fullscreen:    toolButton({
                  id: 'fullscreen',
                  title: fullscreend ? 'Close' : 'Fullscreen',
                  icon:  fullscreend ? faXmark : faArrowUpRightFromSquare,
                  click: onFullscreen,
                }),
    fullfullscreen:    toolButton({
                  id: 'fullfullscreen',
                  title: 'Fullscreen',
                  icon:  faTv,
                  click: onFullFullscreen,
                }),
  }
  
  const overlayStyle = winref1.current != null ? {
    width: winref1.current.clientWidth,
    height: winref1.current.clientHeight,
    marginTop: -winref1.current.clientHeight,
  } : {}

  const basicFullscreen = fullscreend && baseDim == null
  const fittedFullscreen = fullscreend && baseDim != null
  // const fittedFullscreen = true
  // const baseDim = {w: 1, h: 1,}

  const rootStyle = (
    basicFullscreen ? {
      position: 'fixed',
      zIndex: '100',
      inset: '20px',
    } :
    fittedFullscreen ? {
      width: '100%',
      height: '100%',
    } : {
      alignSelf: 'flex-start',
    }
  )
  if (noshrink)
    rootStyle.flexShrink = '0'

  const titleStyle = (
    fullscreend ? {
      // paddingLeft: '4px',
      paddingRight: '4px',
    } : {
      paddingRight: '6px',
    }
  )

  const bodyStyle = (
    basicFullscreen ? {
      ...winbodystyle,
      height: '100%',
    } :
    fittedFullscreen ? {
      height: '100%',       // debug enable for unitywin (NOP (not fittedfullscreen))
    } : 
    minimized.val && displaynoneonminimize ? {
      display: 'none',
    } :
    minimized.val && !displaynoneonminimize ? {
      height: '0px',
      width: minimizedwidth,
    } : {
      ...winbodystyle,
      overflow: body_overflow,
    }
  )

  const headStyle = (
    minimized.val && displaynoneonminimize ? {
      width: minimizedwidth,
      height: '0px',
    } :
    {
      width: '0px',
      height: '0px',
    }
  )

  // ???
  // fullscreend ? {
  //   // position: 'fixed',
  //   // width: '100%',
  //   // height: '100%',
  //   ...winbodystyle,
  //   // height: 'calc(100% - 22px)',
  // } : {
  //   ...winbodystyle,
  //   overflow: 'hidden',
  // }

  const win = (
    <div
      id={`window_${id}`}
      ref={winref1}
      className={`window ${highlight?.val ? 'highlight' : ''} ${fullscreend ? 'fullscreen' : ''}`}
      onMouseEnter={() => hover.set(true)}
      onMouseLeave={() => hover.set(false)}
      style={rootStyle}
    >
      <div className={`titlebar ${minimized.val ? 'minimized' : ''} ${highlight?.val ? 'highlight' : ''}`}>
        {minimizable && !fullscreend &&
          tools.minimize}
        {fullscreend &&
          tools.fullscreen}
        <span className='title' style={titleStyle}>{title}</span>
        {evaluating ?
          tools.evaling
          : ((true || fullscreend) && !minimized.val &&
            <div className='toolrow'>
              {addTools}
              {/* {fullscreenable &&
                tools.fullscreen} */}
              {/* {tools.fullfullscreen} */}
            </div>)
        }
        {/* {tools.fullscreen} */}
      </div>
      <div style={headStyle} />
      <div ref={bodyref1} className='windowBody' style={bodyStyle}>
        {content}
        {/* {!minimized.val &&
          content} */}
      </div>
      {/* {highlight?.val && 
        <div className='overlay' style={overlayStyle} />} */}
    </div>
  )

  const wrappedWin = fittedFullscreen ? fullscreenWrap(win, baseDim.w/(baseDim.h+22))
                                      : win
  return wrappedWin
}
