export default "using System.Collections.Generic;\nusing UnityEngine;\n\nusing Newtonsoft.Json;\n\nusing v2 = UnityEngine.Vector2;\nusing v3 = UnityEngine.Vector3;\nusing Gob = UnityEngine.GameObject;\n\npublic class BlockGroup : MonoPlus {\n\tpublic Main main;\n\tpublic bool hasCollided;\n\tpublic v2 vel;\n\n\tvoid OnCollision(Collision2D col) {\n\t\tbool hitGroup = false;\n\t\t\n\t\tHashSet<(Gob,v3)> toKill = new();\n\t\tfor (int i = 0; i < col.contactCount; i++) {\n\t\t\tvar contact = col.GetContact(i);\n\t\t\tGob b1 = contact.collider.gameObject;\n\t\t\tGob b2 = contact.otherCollider.gameObject;\n\t\t\tif (b1.tag == b2.tag) {\n\t\t\t\ttoKill.Add((b1,contact.point));\n\t\t\t\ttoKill.Add((b2,contact.point));\n\t\t\t}\n\n\t\t\tGob parent = contact.collider.gameObject.Parent();\n\t\t\tbool hitBlock = parent != null && parent.gc<BlockGroup>() != null;\n\t\t\tbool hitFloor = contact.collider.gameObject.name == \"floor\";\n\t\t\tif (hitBlock || hitFloor)\n\t\t\t\thitGroup = true;\n\t\t}\n\t\tforeach (var (gob,point) in toKill)\n\t\t\tmain.KillAdjacent(gob, point);\n\t\t\n\t\tif (hitGroup && main.hitHapticTimer.ready) {\n\t\t\tUtil.Haptic(HapticStrength.Light);\n\t\t\tmain.hitHapticTimer.Reset();\n\t\t}\n\n\t\tif (hitGroup && !hasCollided) {\n\t\t\thasCollided = true;\n\t\t\tmain.OnFirstCollision();\n\t\t}\n\t}\n\tvoid OnCollisionEnter2D(Collision2D col) {\n\t\tOnCollision(col);\n\t}\n\tvoid OnCollisionStay2D(Collision2D col) {\n\t\tOnCollision(col);\n\t}\n}";