// std util
export const log = console.log
export const clamp = (n, min, max) => {
  return Math.min(Math.max(n, min), max)
}
export const range = (len) => {
  const arr = []
  for (let i = 0; i < len; i++)
    arr.push(i)
  return arr
}
export const partition = (array, n, step) => {
  step = step == null ? n : step
  const res = []
  for (var i = 0; i < array.length; i += step) {
    res.push(array.slice(i, i+n))
  }
  return res
  // return array.length ? [array.splice(0, n)].concat(partition(array, n)) : []
}
export const shuffle = (array) => {
  let currentIndex = array.length;

  // While there remain elements to shuffle...
  while (currentIndex != 0) {

    // Pick a remaining element...
    let randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex--;

    // And swap it with the current element.
    [array[currentIndex], array[randomIndex]] = [
      array[randomIndex], array[currentIndex]];
  }
}
export const mapo = (obj, fn=()=>{}, path=[]) => {
  for (var property in obj) {
      if (obj.hasOwnProperty(property)) {
          if (typeof obj[property] == 'object') {
            const path1 = path.concat([property])
            fn(property, obj[property], path1)
            mapo(obj[property], fn, path1)
          }
      }
  }
}
export const access = (obj, path) => path.reduce((o,k) => {return o[k]}, obj)
export const formatResult = (str) => JSON.stringify(str, null, '  ')

// dom util
export const inViewport = (el, window, thresh=0) => {
  if (!el)
    return false
  const winheight = window.innerHeight
  const rect = el.getBoundingClientRect() 
  var amtVisible = rect.height
  if (rect.top < 0)
    amtVisible = rect.bottom
  else if (rect.bottom > winheight)
    amtVisible = winheight - rect.top
  const percVisible = amtVisible/rect.height
  return percVisible > thresh
}

