export const atomStored = (key, val0) => {
  return atomWithStorage(key, val0)
}
export const makeAtom = (atom) => {
  const [val, set] = atom == null ? [null, ()=>{}]
                                  : useAtom(atom)
  return {val, set}
}
export const atomWithListeners = (initialValue) => {
  const baseAtom = atom(initialValue)
  const listenersAtom = atom([])
  const anAtom = atom(
    (get) => get(baseAtom),
    (get, set, arg) => {
      const prevVal = get(baseAtom)
      set(baseAtom, arg)
      const newVal = get(baseAtom)
      get(listenersAtom).forEach((callback) => {
        callback(get, set, newVal, prevVal)
      })
    },
  )
  const useListener = (callback) => {
    const setListeners = useSetAtom(listenersAtom)
    useEffect(() => {
      setListeners((prev) => [...prev, callback])
      return () =>
        setListeners((prev) => {
          const index = prev.indexOf(callback)
          return [...prev.slice(0, index), ...prev.slice(index + 1)]
        })
    }, [setListeners, callback])
  }
  return [anAtom, useListener]
}


