const WIDGE = {}
const widge = (id, n, color) => {
  WIDGE[id] = {
    id,
    $n: atom(n),
    $color: atom(color),
  }
}
const link = (prop, id0, id1) => {
  WIDGE[id0][`${prop}_next`] = WIDGE[id1][prop]
}
const chain = (prop, ...ids) => {
  const pairs = partition(ids,2,1).filter(pair => pair.length==2)
  pairs.forEach(([id0, id1]) => link(prop, id0, id1))
}
const widgeProps = (id) => {
  return WIDGE[id]
}
const Widge = ({id}) => {
  const {$n, $color, $n_next, $color_next} = widgeProps(id)

  // log('Widge (id,$n,$color,$n_next,$color_next)',id,$n,$color,$n_next,$color_next)
  log('Widge '+id)

  const n = makeAtom($n)
  const color = makeAtom($color)

  const nNext = makeAtom($n_next)
  const colorNext = makeAtom($color_next)

  useEffect(() => nNext.set(n.val),
    [n.val])
  useEffect(() => colorNext.set(color.val),
    [color.val])

  return (
    <div style = {{
      backgroundColor: color.val,
      margin: '10px',
      border: '1px solid lightgrey',
    }}>
      <h3>{id}</h3>
      
      n<input type='number' value={n.val} onChange={evt => n.set(evt.target.value)}></input><br/>
      n<input type='text' value={color.val} onChange={evt => color.set(evt.target.value)}></input><br/>

      <br/>
      n={n.val}<br/>
      color={color.val}<br/>
    </div>
  )
}
